/* Original study guidance and links. No commercial book or course text is included. */
const BOOKS=[
  {id:'moji',title:'MOJi辞書 / MOJiTest',tag:'查词与备考工具',url:'https://test.mojidict.com/',detail:'辞書用于查词和词汇积累；Test 用于背词和专项练习。产品功能与课程需要分别选择。',use:'先跟着以前学过的词和基础内容复习。进入 N2 后，选一个固定词书来源；别同时在多个工具里重复背整套词库。',source:'https://webpc-quasi-ten.mojidict.com/support/',sourceLabel:'MOJi 官方产品说明'},
  {id:'red',title:'N2 红宝书 · 文字词汇',tag:'系统词汇学习',url:'https://haidii.com/sc/12009/?chn=wxhd&sales=1803kx',detail:'红宝书侧重文字词汇。已找到出版社授权的 Android / iOS 配套产品入口；纸书与数字版应核对版次。',use:'基础恢复后，从你手上的正版版本开始。每天只学适量新词，同时看例句、听读音，把容易忘的词加入复习。',source:'https://haidii.com/sc/12009/?chn=wxhd&sales=1803kx',sourceLabel:'海笛 · 出版社授权产品'},
  {id:'blue',title:'N2 蓝宝书 · 文法',tag:'语法讲解与练习',url:'https://www.ecustpress.cn/',detail:'蓝宝书侧重文法讲解与练习。出版社为华东理工大学出版社；本次未核实最新版的单册书目页。',use:'每周约 3 个新语法。先检查接续，再读例句、自己造句、做配套小题；第二天脱离书回想一次。',source:'https://www.ecustpress.cn/',sourceLabel:'华东理工大学出版社'},
  {id:'listening',title:'真人听力 · 官方练习册',tag:'每天保留的专项',url:'https://www.jlpt.jp/e/samples/sampleindex.html',detail:'官方练习册提供听力音频、脚本与答案。先用合适级别恢复理解，再逐步进入 N2 题型。',use:'每天 12 分钟精听一小段。不是只答题：听不出来的熟词也要标出，跟读后无稿复听。',source:'https://www.jlpt.jp/e/samples/sampleindex.html',sourceLabel:'JLPT 官方练习资料'},
  {id:'reading',title:'阅读与完整模拟',tag:'补齐完整备考的部分',url:'https://www.jlpt.jp/e/samples/sampleindex.html',detail:'词汇和语法需要在篇章里运用。用正式练习了解阅读题型，后期还要适应整场考试的时间分配。',use:'与语法隔天交替。先短文、找证据句，再计时；考前完整模拟需要额外预留一整段时间。',source:'https://www.jlpt.jp/e/samples/sampleindex.html',sourceLabel:'JLPT 官方练习资料'}
];
function renderMaterials(){return `${officialWordAudioSourcesCard()}<div class="notice">MOJi、红宝书和蓝宝书已放入学习路线。这里提供配套方法、官方入口和进度记录；完整教材内容在你的正版书或官方平台中学习。本站没有账号关联、自动同步或整书题库。</div><div class="split"><section class="card"><div class="card-head"><h2>先补基础，再用 N2 教材。</h2><span class="pill">你的学习顺序</span></div><ol class="info-list"><li>前 6–8 周：复习高考旧教材的变形、助词和常用表达。MOJi 作查词工具；本站基础小测用于找弱项。基础真人音频也可使用 <a href="https://www2.jpfbj.cn/irodori/" target="_blank" rel="noopener">IRODORI 官方中文教材 ↗</a>（A1/A2 日常日语，按薄弱部分选学）。</li><li>基础稳定后：红宝书 / 一个固定词书来源 + 蓝宝书，逐步积累 N2 词汇和语法。</li><li>一直保留：真人短听力，阅读与语法交替。</li><li>考前检验：用新题自评和完整模拟判断准备程度。</li></ol><div class="table-wrap"><table><thead><tr><th>每天 30 分钟</th><th>配套内容</th></tr></thead><tbody><tr><td>8 分钟</td><td>词书旧词优先；最多 5 个新词</td></tr><tr><td>12 分钟</td><td>短听力精听、跟读、无稿复听</td></tr><tr><td>10 分钟</td><td>蓝宝书一个语法点，或短阅读</td></tr></tbody></table></div><p class="panel-note">这是根据你的时间安排提出的组合路线。词典、词书和语法书各有用途，还需听力与阅读。</p></section><section class="card" style="align-self:start"><h2>如果你想跟着老师上课</h2><p class="subtext">MOJi小课堂是独立的课程平台。选择时先确认课程起点、覆盖的考试科目、能否回看、每课用时，以及是否适合 2027 年夏季目标。先试听，再判断能否放进每天 30 分钟。</p><a class="button secondary" target="_blank" rel="noopener" href="https://m.mojidict.com/classroom">打开 MOJi小课堂 ↗</a><p class="panel-note">检索到的冲刺课不能直接当作从基础到 N2 的完整课程。本次未核实适合你的 2027 年全程班。</p></section></div><div class="grammar-grid">${BOOKS.map(b=>{const last=state.materials.filter(m=>m.resource===b.id).at(-1);return `<section class="card"><span class="pill">${b.tag}</span><h2 style="margin-top:15px">${b.title}</h2><p class="subtext">${b.detail}</p><p class="subtext">${b.use}</p><div class="notice" style="margin-top:18px;margin-bottom:15px"><strong>${last?'最近学到：'+esc(last.position):'还没记录学习位置'}</strong>${last?`<br><small>${last.date} · ${esc(last.note||'下次从这里继续。')}</small>`:''}</div><div class="button-row"><a class="button ghost" href="${b.url}" target="_blank" rel="noopener">查看资源 ↗</a><button class="button secondary" data-action="material-log" data-id="${b.id}">记录学到哪里</button></div><p class="panel-note">信息来源：<a href="${b.source}" target="_blank" rel="noopener">${b.sourceLabel} ↗</a></p></section>`;}).join('')}</div><section class="card section-gap"><h2>别把复习时间分散。</h2><p class="subtext">一个词汇主工具就够了：在 MOJi 里背词时，本站主要记录教材位置和易忘词；使用本站词卡时，MOJi 主要查词。红宝书和蓝宝书不是必须同时买整套，先恢复已有知识，再根据新题表现决定需要什么资料。</p></section>`;}
function materialForm(id){const b=BOOKS.find(x=>x.id===id)||BOOKS[0];modal('记录教材进度',`<p class="subtext">记下你实际完成的页码、单元或课程名称，不用追赶虚假的百分比。</p><form id="material-form"><label class="subtext">学习资料<select name="resource">${BOOKS.map(x=>`<option value="${x.id}" ${b.id===x.id?'selected':''}>${x.title}</option>`).join('')}</select></label><label class="subtext section-gap">学到哪里 *<input name="position" required maxlength="300" placeholder="例如：第2单元 / 第18页 / 动词て形复习"></label><label class="subtext section-gap">今天的发现与下次任务<textarea name="note" maxlength="2000" rows="3" placeholder="如：间に合う的读音容易忘，下次先复习。"></textarea></label><button type="submit" class="button section-gap">保存进度</button></form>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action="material-log"]');if(el)materialForm(el.dataset.id);});
document.addEventListener('submit',e=>{if(e.target.id!=='material-form')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.position.trim())return;const b=BOOKS.find(x=>x.id===v.resource);if(!b)return;const m={id:'m-'+Date.now(),date:today,resource:b.id,position:v.position.trim(),note:v.note.trim()};state.materials.push(m);addNote(m.id,b.title+' · '+m.position,m.note||'下次从这里继续。','教材');persist();$('#modal').close();render();toast('教材进度已保存在本机。');});
